#include "GameClient/GameClient.h"

GameMessageDisposition GameClientMessageDispatcher::translateGameMessage(const GameMessage *msg)
{
	GameMessage::Type type = msg->getType();
	if (type >= GameMessage::MSG_BEGIN_NETWORK_MESSAGES && type <= GameMessage::MSG_END_NETWORK_MESSAGES)
		return KEEP_MESSAGE;
	if (type == GameMessage::MSG_NEW_GAME
		|| type == GameMessage::MSG_CLEAR_GAME_DATA
		|| type == GameMessage::MSG_0x7D9
		|| type == GameMessage::MSG_0x7ED
		|| type == GameMessage::MSG_LW_DONE_SESSION
		|| type == GameMessage::MSG_START_LIVING_WORLD_LOGIC
		|| type == GameMessage::MSG_START_LINEAR_CAMPAIGN
		|| type == GameMessage::MSG_EXIT_LINEAR_CAMPAIGN
		|| type == GameMessage::MSG_CURRENT_LINEAR_CAMPAIGN_MISSION_COMPLETE)
		return KEEP_MESSAGE;
	return DESTROY_MESSAGE;
}
